

const prisma = require("../config/prisma");
const generateEmployeeId = require("../utils/generateEmployeeId");

// ---------------- CREATE EMPLOYEE ----------------
exports.createEmployee = async (data) => {
  // 1. Create employee (employeeNo auto-generated by DB)
  const employee = await prisma.employee.create({
    data: {
      name: data.name,
      email: data.email,
      department: data.department,
      position: data.position,
      joiningDate: new Date(data.joiningDate),
    },
  });

  // 2. Generate human-readable employeeId (EMP-001)
  const employeeId = generateEmployeeId(employee.employeeNo);

  // 3. Update employee with employeeId
  return prisma.employee.update({
    where: { id: employee.id },
    data: { employeeId },
  });
};

// ---------------- GET ALL EMPLOYEES (SEARCH + SORT) ----------------
exports.getAllEmployees = async (search) => {
  
  const employees = await prisma.employee.findMany({
    where: search
      ? {
          OR: [
            { employeeId: { contains: search, mode: "insensitive" } },
            { name: { contains: search, mode: "insensitive" } },
            { email: { contains: search, mode: "insensitive" } },
            { department: { contains: search, mode: "insensitive" } },
          ],
        }
      : undefined,
    orderBy: {
      employeeNo: "asc",
    },
  });

  // Last allocation date code
  const result = await Promise.all(
    employees.map(async (emp) => {
      const lastAsset = await prisma.employeeAsset.findFirst({
        where: { employeeId: emp.id },
        orderBy: { allocatedDate: "desc" },
        select: { allocatedDate: true },
      });

      const assetCount = await prisma.employeeAsset.count({
        where: { employeeId: emp.id },
      });

      return {
        id: emp.id,
        employeeId: emp.employeeId,
        name: emp.name,
        email: emp.email,
        department: emp.department,
        position: emp.position,
        joiningDate: emp.joiningDate,

        
        assets: assetCount,
        lastAllocated: lastAsset?.allocatedDate || null,
      };
    })
  );

  return result;
};



// ---------------- GET EMPLOYEE BY ID ----------------
exports.getEmployeeById = async (id) => {
  return prisma.employee.findUnique({
    where: { id },
  });
};

// ---------------- UPDATE EMPLOYEE ----------------
exports.updateEmployee = async (id, data) => {
  if (data.joiningDate) {
    data.joiningDate = new Date(data.joiningDate);
  }

  return prisma.employee.update({
    where: { id },
    data,
  });
};

// ---------------- DELETE EMPLOYEE ----------------
exports.deleteEmployee = async (id) => {
  return prisma.employee.delete({
    where: { id },
  });
};
